    background-color: rgba(100, 100, 100, 0.7);
}

.v-theme--dark ::-webkit-scrollbar-thumb {
    background-color: rgba(200, 200, 200, 0.3);
}

.v-theme--dark ::-webkit-scrollbar-thumb:hover {
    background-color: rgba(200, 200, 200, 0.5);
}

.required-field .v-label::after {
    content: " *";
    color: red;
}

* {
    scrollbar-width: thin !important;
    font-family: "Plus Jakarta Sans", "Cairo", system-ui, sans-serif;
    font-optical-sizing: auto;
    letter-spacing: 0;
    scrollbar-color: rgba(100, 100, 100, 0.4) transparent;
}

/* Arabic uses Cairo; Latin keeps Plus Jakarta. No global letter-spacing. */
[dir="rtl"] *,
[dir="rtl"] {
    font-family: "Cairo", "Plus Jakarta Sans", system-ui, sans-serif;
    letter-spacing: 0;
}

.v-theme--dark * {
    scrollbar-color: rgba(200, 200, 200, 0.3) transparent;
}
html {
    overflow-y: auto;
}

.tiny-autocomplete {
    font-size: 0.75rem; /* reduce font globally */
}

.tiny-autocomplete .v-field__input {
    font-size: 0.75rem;
    min-height: 32px; /* reduce height */
    padding-top: 2px;
    padding-bottom: 2px;
}

.tiny-autocomplete .v-field__label {
    font-size: 0.7rem;
}

.show-in-print {
    display: none;
}
.printable-header {
    page-break-after: auto !important;
    page-break-inside: avoid !important;
    orphans: 3 !important;
    widows: 3 !important;
}

@media print {
    .print-hide {
        display: none !important;
    }

    html,
    body {
        margin: 0 !important;
        padding: 0 !important;
        color: black !important;
    }
    .show-in-print {
        display: inherit;
    }
}
@page {
    size: A4;
    margin-top: 1cm !important;
    margin-bottom: 1cm !important;
}

/* ---------------------------------------------------------------------------
 * Payer (checkout) surface — one focused column, no app chrome.
 * ------------------------------------------------------------------------- */
.pg-checkout {
    min-height: 100dvh;
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    gap: 12px;
    padding: 24px 16px 60px;
    background: linear-gradient(170deg, #f4f7fb 0%, #e6eefb 55%, #e7f6f3 100%);
}

.pg-checkout__title {
    font-size: 17px;
    font-weight: 700;
}

@media (max-width: 600px) {
    .pg-checkout {
        justify-content: flex-start;
        padding: 16px 12px 48px;
    }
}
