.show-in-print {
    display: none;
}
.printable-header {
    page-break-after: auto !important;
    page-break-inside: avoid !important;
    orphans: 3 !important;
    widows: 3 !important;
}

@media print {
    .print-hide {
        display: none !important;
    }

    html,
    body {
        margin: 0 !important;
        padding: 0 !important;
        color: black !important;
    }
    .show-in-print {
        display: inherit;
    }
}
@page {
    size: A4;
    margin-top: 1cm !important;
    margin-bottom: 1cm !important;
}

/* ---------------------------------------------------------------------------
 * Application shell (merchant)
 * A fixed app bar + navigation drawer + scrolling main surface. The layout is
 * owned by the shell; pages are plain content inside `.pg-page`.
 * ------------------------------------------------------------------------- */
.pg-app-bar {
    border-bottom: 1px solid var(--fintech-border);
    backdrop-filter: blur(10px);
    -webkit-backdrop-filter: blur(10px);
}

.pg-app-bar .v-toolbar__content {
    gap: 6px;
    padding-inline: 12px;
}

.pg-app-bar__brand {
    display: flex;
    align-items: center;
    gap: 10px;
    min-width: 0;
    margin-inline-start: 4px;
}

.pg-app-bar__title {
    font-size: 15px;
    font-weight: 800;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}

.pg-spacer {
    flex: 1 1 auto;
}

.pg-user-btn {
    text-transform: none;
    letter-spacing: 0;
    padding-inline: 8px;
}

.pg-user-btn__name {
    margin-inline-start: 8px;
    font-size: 13px;
    font-weight: 700;
    max-width: 160px;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
}

.pg-avatar {
    background: linear-gradient(135deg, rgb(var(--v-theme-primary)), rgb(var(--v-theme-accent)));
    color: white;
    font-weight: 800;
}

.pg-drawer {
    border-inline-end: 1px solid var(--fintech-border);
    display: flex;
    flex-direction: column;
    height: 100%;
    max-height: 100dvh;
    overflow: hidden;
}

.pg-drawer .v-navigation-drawer__content {
    display: flex;
    flex-direction: column;
    height: 100%;
    min-height: 0;
    overflow: hidden;
}

.pg-drawer__brand {
    display: flex;
    flex: 0 0 auto;
    align-items: center;
    gap: 12px;
    padding: 18px 18px 14px;
}

.pg-drawer__brand-text {
    display: flex;
    flex-direction: column;
    min-width: 0;
}

.pg-drawer__title {
    font-size: 15px;
    font-weight: 800;
    line-height: 1.2;
}

.pg-drawer__subtitle {
    font-size: 11px;
    opacity: 0.6;
}

.pg-drawer .v-navigation-drawer__content .pg-nav {
    flex: 1 1 auto;
    min-height: 0;
    overflow-y: auto;
    overscroll-behavior: contain;
    -webkit-overflow-scrolling: touch;
    padding: 8px 10px 16px;
}

.pg-nav__group {
    margin-bottom: 8px;
}

.pg-nav .v-list-subheader,
.pg-nav__section {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 8px;
    min-height: 38px;
    margin-top: 2px;
    padding-inline: 12px;
    border-radius: 10px;
    font-size: 11px;
    font-weight: 800;
    letter-spacing: 0.06em;
    text-transform: uppercase;
    opacity: 0.62;
    cursor: pointer;
    user-select: none;
}

.pg-nav__section-wrap {
    outline: none;
}

.pg-nav__section:hover {
    background: rgba(var(--v-theme-primary), 0.08);
    opacity: 0.9;
}

.pg-nav__section-wrap:focus-visible .pg-nav__section {
    background: rgba(var(--v-theme-primary), 0.08);
    box-shadow: 0 0 0 2px rgba(var(--v-theme-primary), 0.35);
    opacity: 0.9;
}

.pg-nav__section-title {
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
}

.pg-nav__section .v-icon {
    flex: 0 0 auto;
    opacity: 0.7;
}

.pg-nav .v-list-group__items {
    padding-top: 2px;
}

.pg-nav .v-list-item {
    margin-bottom: 2px;
}

.pg-nav .v-list-item--active {
    background: rgba(var(--v-theme-primary), 0.1);
}

.pg-drawer__footer {
    flex: 0 0 auto;
    padding: 12px 16px 16px;
    border-top: 1px solid var(--fintech-border);
}

.pg-main {
    background: rgb(var(--v-theme-background));
}

.pg-page {
    display: flex;
    flex-direction: column;
    gap: 18px;
    width: 100%;
    max-width: 1600px;
    margin-inline: auto;
    padding: 24px 28px 40px;
}

@media (max-width: 960px) {
    .pg-page {
        padding: 16px 14px 32px;
    }

    .pg-user-btn__name {
        display: none;
    }
}

@media (max-width: 600px) {
    .pg-app-bar__title {
        display: none;
    }
}
