 const frontendBuildEnv = (frontend: string, config: DeployConfig): Record<string, string> => {
   if (frontend === "admin-front") {
     return {
       VITE_SHOW_SNAPSHOT_EXPORT_CHECKLIST: String(config.ADMIN_SHOW_SNAPSHOT_EXPORT_CHECKLIST),
     };
   }
   return {};
 };

