design/session-ses_e8c2.md:1996:  "content": "# LAN-only reverse proxy for the admin back office.
# The listener is bound to the private interface only. There is no public virtual host
# and no router port forwarding for this server.

upstream admin_back {
    server 127.0.0.1:4101;
    keepalive 16;
}

server {
    listen 10.0.0.10:8443 ssl;
    listen [fd00::10]:8443 ssl;
    server_name admin.internal;

    allow 10.0.0.0/8;
    allow 192.168.0.0/16;
    allow 172.16.0.0/12;
    deny all;

    ssl_certificate     /etc/letsencrypt/live/admin.internal/fullchain.pem;
    ssl_certificate_key /etc/letsencrypt/live/admin.internal/privkey.pem;
    ssl_protocols TLSv1.3;
    ssl_prefer_server_ciphers off;
    ssl_session_cache shared:SSL:10m;
    ssl_session_timeout 1d;

    add_header Strict-Transport-Security "max-age=63072000; includeSubDomains" always;
    add_header X-Content-Type-Options "nosniff" always;
    add_header X-Frame-Options "DENY" always;
    add_header Referrer-Policy "no-referrer" always;
    add_header Content-Security-Policy "default-src 'self'; img-src 'self' data: https:; style-src 'self' 'unsafe-inline'; script-src 'self'; frame-ancestors 'none'; base-uri 'self'; form-action 'self'" always;

    client_max_body_size 15m;

    root /var/www/admin-front/dist;
    index index.html;

    location /api/ {
        proxy_pass http://admin_back;
        proxy_http_version 1.1;
        proxy_set_header Host $host;
        proxy_set_header X-Real-IP $remote_addr;
        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
        proxy_set_header X-Forwarded-Proto https;
        proxy_set_header X-Request-Id $request_id;
        proxy_read_timeout 60s;
    }

    location / {
        try_files $uri $uri/ /index.html;
    }
}
