                         row.reportRef,
                         row.reportType,
                         row.authority,
                         row.status,
                         row.subjectType,
                         row.subjectName,
                         row.amlCaseId ?? "",
                         row.periodStart ?? "",
                         row.periodEnd ?? "",
                         row.submissionRef ?? "",
                         row.submittedAt ?? "",
                         row.createdAt,
                         row.ageHours,
                     ]
                         .map(escape)
                         .join(","),
                 ),
             ];
             const blob = new Blob([lines.join("\n")], { type: "text/csv;charset=utf-8" });
             const url = URL.createObjectURL(blob);
             const link = document.createElement("a");
             link.href = url;
             link.download = `aml-reports-${new Date().toISOString().slice(0, 10)}.csv`;
