             const payload = response.data?.data ?? response.data ?? {};
             selected.value = { ...selected.value, status: payload.status ?? ackStatus.value };
             detailsOpen.value = false;
             showSnackBar({ type: "success", message: t("Authority decision recorded") });
             refreshAll();
