     if (value === null || value === undefined) {
         return "";
     }
     if (typeof value === "string") {
         return value;
     }
     if (typeof value === "number" || typeof value === "boolean") {
         return String(value);
     }
     try {
         return JSON.stringify(value, null, 2);
     } catch {
         return String(value);
     }
 };

