const titles = [
  "Snapshot export checklist",
  "Activity export checklist",
  "Summary export checklist",
  "Team export checklist",
  "Process checklist",
  "Upload checklist",
  "Source edit checklist",
  "Rail edit checklist",
  "Rail field checklist",
  "Decision checklist",
];

const generic = {
  total: 0, totalPending: 0, active: 0, blocked: 0, suspended: 0, pending: 0, rejected: 0, closed: 0,
  expired: 0, expiringSoon: 0, emergencyDue: 0, oldestAgeHours: 0,
  routes: { healthy: 0, degraded: 0, openBreaker: 0 },
  byDomain: [], byState: [], bySubjectType: [], byRole: [], byStatus: [], byType: [],
  items: [], rows: [], runs: [], recentActivity: [], approvals: [], users: [], rails: [], routes: [],
  gateways: [], disputes: [], adjustments: [], cashouts: [], operatorCases: [], amlCases: [],
};

const browser = await chromium.launch();
const context = await browser.newContext();
await context.addInitScript(() => {
  localStorage.setItem("locale-name", "en");
  localStorage.setItem("PAYMENT_GATEWAY:ADMIN:USER", JSON.stringify({
    token: "test-token", refreshToken: null,
    userInfo: {
      id: "1", name: "Tester", username: "tester", role: "GATEWAY_ADMIN",
      email: null, phone: null,
      authoritiesMap: {
        "security:read": true, "approvals.approve": true, "approvals.reject": true,
        "approval:read": true, "finance:read": true, "users:read": true,
      },
      isMaker: false, isChecker: false,
    },
  }));
});
if (visibleOverride) {
  await context.route("**/runtime-config.js", (route) => route.fulfill({
    status: 200, contentType: "application/javascript",
    body: 'window.__PG_RUNTIME_CONFIG__ = {"showChecklists":true,"showSnapshotExportChecklist":true};',
  }));
}
await context.route("**/api/**", async (route) => {
  const url = route.request().url();
  let body;
  if (url.includes("/options/")) body = { data: [] };
  else if (url.includes("/summary")) body = { data: generic };
  else if (url.includes("/stats/overview")) body = { data: generic };
  else if (url.includes("/stats/recent-activity")) body = { data: { recentActivity: [] } };
  else if (url.includes("page=") || url.includes("pageSize=")) body = { data: [], total: 0 };
  else body = { data: generic };
  await route.fulfill({ status: 200, contentType: "application/json", body: JSON.stringify(body) });
});

const page = await context.newPage();
for (const route of routes) {
  const errors = [];
  page.removeAllListeners("pageerror");
  page.on("pageerror", (e) => errors.push(String(e)));
  await page.goto(`http://127.0.0.1:8443${route}`, { waitUntil: "networkidle" });
  await page.waitForTimeout(900);
  const body = await page.locator("body").innerText();
  const found = titles.filter((title) => body.includes(title));
  console.log(`${route}: found=${JSON.stringify(found)} errors=${errors.length}`);
}
await browser.close();
