     if (seconds < 60) return `${formatPlainNumber(seconds)}s`;
     if (seconds < 3600) return `${formatPlainNumber(Math.round(seconds / 60))}m`;
     if (seconds < 86_400) return `${formatPlainNumber(Math.round(seconds / 3600))}h`;
