             },
         },
     });

     worksheet.columns = headers?.map((h) => {
         return {
             key: h.key || h.text,
             header: h.text,
         } satisfies Partial<ExcelJS.Column>;
     });

     const headerRow = worksheet.getRow(1);
     headerRow.fill = {
         type: "pattern",
