   // 1. The backend source.
   runner.sync({
     target: host.ssh,
     local: join(REPO_ROOT, service.sourceDir),
     remote: appDir,
     excludes: ["node_modules", ".git", "dist", "generated", "test", "certs", ".certs", "*.log", ".env"],
   });

   // 2. The frontend build (already compiled locally in step 2).
   if (frontend) {
