router.post(
  "/operator-cases/bulk-assign",
  coreForward({
    method: "POST",
    path: () => "/internal/admin/operator-cases/bulk-assign",
    schema: bulkAssignSchema,
  }),
);

router.post(
  "/operator-cases/bulk-state",
