router.get(
  "/operator-cases/summary/export",
  coreForward({
    method: "GET",
    path: () => "/internal/admin/operator-cases/summary/export",
  }),
);

router.get(
  "/operator-cases/:id",
  coreForward({
    method: "GET",
    path: (context) => `/internal/admin/operator-cases/${encodeURIComponent(context.params.id ?? "")}`,
    paramsSchema: idParamsSchema,
  }),
