router.post(
  "/attempts/:id/inquire",
  coreForward({
    method: "POST",
    path: (context) => `/internal/admin/attempts/${encodeURIComponent(context.params.id ?? "")}/inquire`,
    paramsSchema: idParamsSchema,
    schema: inquireSchema,
  }),
