        attemptStatus: "VERIFYING",
        terminalAt: null,
        supportsStatusCheck: true,
      }).eligible,
    ).toBe(true);
  });

  test("resolved and checker-pending cases are never reopened by bulk inquiry", () => {
    expect(
      operatorCaseInquiryEligibility({
