           businessCategory: merchant.businessCategory,
           riskTier: merchant.riskTier,
           kybStatus: merchant.kybStatus,
           nextKybReviewAt: merchant.nextKybReviewAt,
           suspensionNotes: merchant.suspensionNotes,
