         }
       : {}),
     ...(flags.canFinancial
       ? {
           payoutBankDetailsJson: merchant.payoutBankDetailsJson,
           commissionReceivableCeiling: merchant.commissionReceivableCeiling,
           negativeBalanceCeiling: merchant.negativeBalanceCeiling,
         }
