mkdir -p admin-front/src/pages/operator-cases/inquiries; cat > admin-front/src/pages/operator-cases/inquiries/index.tsx <<'TSX'
import { dc } from "kt-dc";
import { computed, ref } from "vue";
import { useLocale, useTheme } from "vuetify";
import { useRouter } from "vue-router";
import { VAlert, VBtn, VCard, VCardText, VDialog, VTextarea } from "vuetify/components";
import ScreenContainer from "@/components/ScreenContainer";
import { PageHeader } from "@/components/PageHeader";
import { ThemedView } from "@/components/ThemedView";
import { ThemedText } from "@/components/ThemedText";
import { StatusChip } from "@/components/StatusChip";
import { ApiTable } from "@/components/Table/ApiTable";
import TableFilters from "@/components/Table/TableFilters";
import { buildFilterQuery, type FilterValues } from "@/components/Table/filters";
import { tableRegistry } from "@/components/Table/tableRegistry";
import { statusTone } from "@/components/Table/statusTone";
import type { TableHeader } from "@/components/Table/types";
import { api } from "@/state/api";
import { hasOneOfAuthorities } from "@/state/user";
import { urlsMap } from "@/constants/urlsMap";
import { extractApiErrorMessage } from "@/utils/errors/extractor";
import { showSnackBar } from "@/utils/snackBar";
import { formatDateTime } from "../operatorCaseHelp";
import type {
    GatewayInquirySchedule,
    GatewayInquiryScheduleSummary,
    GatewayInquiryScheduleStatus,
} from "../types";

const filterDefinitions = tableRegistry.GatewayInquiries?.filters ?? [];

const statusLabel = (status: string): string =>
    status
        .replaceAll("_", " ")
        .toLowerCase()
        .replace(/^\w/, (letter) => letter.toUpperCase());

const sourceLabel = (source: string): string => {
    if (source === "OPERATOR_CASE") return "Operator case";
    if (source === "AUTOMATIC") return "Automatic";
    return statusLabel(source);
};

const summaryCards = (summary: GatewayInquiryScheduleSummary | null, t: (key: string) => string) => {
    if (!summary) return [];
    return [
        { key: "SCHEDULED", label: t("Scheduled"), value: summary.scheduled, tone: "info" as const },
        { key: "RUNNING", label: t("Running"), value: summary.running, tone: "primary" as const },
        { key: "RETRYING", label: t("Retrying"), value: summary.retrying, tone: "warning" as const },
        { key: "COMPLETED", label: t("Completed"), value: summary.completed, tone: "success" as const },
        { key: "FAILED", label: t("Failed"), value: summary.failed, tone: "error" as const },
        { key: "CANCELLED", label: t("Cancelled"), value: summary.cancelled, tone: "neutral" as const },
        { key: "EXPIRED", label: t("Expired"), value: summary.expired, tone: "error" as const },
        { key: "OVERDUE", label: t("Overdue"), value: summary.overdue, tone: "warning" as const },
    ];
};

type ActionMode = "cancel" | "run-now" | "retry";

type ScheduleDetail = {
    schedule: GatewayInquirySchedule;
    auditTrail: Array<{
        id: string;
        createdAt: string;
        action: string;
        role: string;
        actor?: { email?: string | null } | null;
        afterJson?: unknown;
    }>;
};

const GatewayInquirySchedulesPage = dc(() => {
    const { t } = useLocale();
    const theme = useTheme();
    const router = useRouter();

    const search = ref<string | null>(null);
    const filters = ref<FilterValues>({});
    const total = ref(0);
    const summary = ref<GatewayInquiryScheduleSummary | null>(null);
    const summaryLoading = ref(false);
    const pageSize = ref(20);
    const refreshHook = ref<{
        reset: () => void;
        refresh: (props: { queryParams?: Record<string, unknown>; nextSkip?: number }) => Promise<void>;
        refreshAsIs: () => void;
    } | null>(null);
    let filterTimer: ReturnType<typeof setTimeout> | undefined;

    const actionMode = ref<ActionMode | null>(null);
    const actionRow = ref<GatewayInquirySchedule | null>(null);
    const actionReason = ref("");
    const actionLoading = ref(false);

    const detailOpen = ref(false);
    const detailLoading = ref(false);
    const detail = ref<ScheduleDetail | null>(null);

    const canAct = computed(() => hasOneOfAuthorities(["attempt:inquire", "case:write", "operator:write"]));
    const cards = computed(() => summaryCards(summary.value, t));

    const loadSummary = async () => {
        summaryLoading.value = true;
        try {
            const response = await api.get(urlsMap.gatewayInquiriesSummary);
            const payload = response.data?.data ?? response.data ?? {};
            summary.value = (payload.summary ?? payload) as GatewayInquiryScheduleSummary;
        } catch {
            summary.value = null;
        } finally {
            summaryLoading.value = false;
        }
    };

    void loadSummary();

    const refreshAll = () => {
        refreshHook.value?.refreshAsIs();
        void loadSummary();
    };

    const onSearch = () => {
        refreshHook.value?.reset();
    };

    const onFiltersChanged = () => {
        if (filterTimer) clearTimeout(filterTimer);
        filterTimer = setTimeout(() => refreshHook.value?.reset(), 300);
    };

    const onFiltersCleared = () => {
        filters.value = {};
        refreshHook.value?.reset();
    };

    const openCase = (row: GatewayInquirySchedule) => {
        if (row.operatorCaseId) {
            void router.push({ name: "OperatorCaseDetail", params: { id: row.operatorCaseId } });
        }
    };

    const openAction = (mode: ActionMode, row: GatewayInquirySchedule) => {
        actionMode.value = mode;
        actionRow.value = row;
        actionReason.value = "";
    };

    const closeAction = () => {
        actionMode.value = null;
        actionRow.value = null;
        actionReason.value = "";
    };

    const actionTitle = computed(() => {
        if (actionMode.value === "cancel") return t("Cancel gateway inquiry");
        if (actionMode.value === "run-now") return t("Run gateway inquiry now");
        if (actionMode.value === "retry") return t("Retry gateway inquiry");
        return "";
    });

    const actionDescription = computed(() => {
        if (actionMode.value === "cancel") return t("The schedule will stop before its next run. The payment attempt itself is not changed.");
        if (actionMode.value === "run-now") return t("The next gateway inquiry will run immediately.");
        if (actionMode.value === "retry") return t("A failed, expired or cancelled inquiry will be scheduled to run again.");
        return "";
    });

    const submitAction = async () => {
        const row = actionRow.value;
        const mode = actionMode.value;
        if (!row || !mode || actionLoading.value) return;
        if (mode === "cancel" && actionReason.value.trim().length < 3) {
            showSnackBar({ type: "warning", message: t("A cancellation reason of at least 3 characters is required") });
            return;
        }
        actionLoading.value = true;
        try {
            const body = { reason: actionReason.value.trim() || undefined };
            if (mode === "cancel") {
                await api.post(urlsMap.gatewayInquiryCancel(row.id), { reason: actionReason.value.trim() });
            } else if (mode === "run-now") {
                await api.post(urlsMap.gatewayInquiryRunNow(row.id), body);
            } else {
                await api.post(urlsMap.gatewayInquiryRetry(row.id), body);
            }
            showSnackBar({
                type: "success",
                message:
                    mode === "cancel"
                        ? t("Gateway inquiry cancelled")
                        : mode === "run-now"
                          ? t("Gateway inquiry will run now")
                          : t("Gateway inquiry retried"),
            });
            closeAction();
            refreshAll();
        } catch (error) {
            showSnackBar({ type: "error", message: extractApiErrorMessage(error) });
        } finally {
            actionLoading.value = false;
        }
    };

    const openDetail = async (row: GatewayInquirySchedule) => {
        detailOpen.value = true;
        detailLoading.value = true;
        detail.value = null;
        try {
            const response = await api.get(urlsMap.gatewayInquiryDetail(row.id));
            const payload = response.data?.data ?? response.data ?? {};
            detail.value = {
                schedule: (payload.schedule ?? row) as GatewayInquirySchedule,
                auditTrail: (payload.auditTrail ?? []) as ScheduleDetail["auditTrail"],
            };
        } catch (error) {
            showSnackBar({ type: "error", message: extractApiErrorMessage(error) });
        } finally {
            detailLoading.value = false;
        }
    };

    const headers: TableHeader<GatewayInquirySchedule>[] = [
        {
            key: "status",
            label: "Status",
            sortKey: "status",
            headerTooltip: "The current state of the persisted gateway inquiry schedule.",
            value: (row) => row.status,
            Value: ({ row }) => (
                <ThemedView style={{ gap: "3px" }}>
                    <StatusChip label={statusLabel(row.status)} tone={statusTone(row.status)} size="small" />
                    {row.isOverdue && <StatusChip label={t("Overdue")} tone="warning" size="x-small" />}
                </ThemedView>
            ),
        },
        {
            key: "case",
            label: "Case",
            value: (row) => row.caseRef ?? row.operatorCaseId ?? "",
            Value: ({ row }) => (
                <VBtn
                    size="small"
                    variant="text"
                    disabled={!row.operatorCaseId}
                    onClick={() => openCase(row)}
                >
                    {row.caseRef || row.operatorCaseId || "—"}
                </VBtn>
            ),
        },
        {
            key: "attempt",
            label: "Attempt",
            value: (row) => row.attemptReference ?? "",
            Value: ({ row }) => (
                <ThemedView style={{ gap: "3px" }}>
                    <ThemedText style={{ fontSize: "12px", fontWeight: 700, direction: "ltr" }}>{row.attemptReference || "—"}</ThemedText>
                    <StatusChip label={row.attemptStatus || t("Unknown")} tone={statusTone(row.attemptStatus)} size="x-small" />
                </ThemedView>
            ),
        },
        {
            key: "merchant",
            label: "Merchant",
            value: (row) => row.merchantName,
            Value: ({ row }) => <ThemedText style={{ fontSize: "12px" }}>{row.merchantName || "—"}</ThemedText>,
        },
        {
            key: "gateway",
            label: "Gateway",
            value: (row) => row.gatewayName ?? row.gatewayCode ?? "",
            Value: ({ row }) => (
                <ThemedView style={{ gap: "2px" }}>
                    <ThemedText style={{ fontSize: "12px", fontWeight: 700 }}>{row.gatewayName || row.gatewayCode || "—"}</ThemedText>
                    <ThemedText style={{ fontSize: "10px", opacity: 0.55 }}>{row.railCode || ""}</ThemedText>
                </ThemedView>
            ),
        },
        {
            key: "source",
            label: "Source",
            sortKey: "source",
            value: (row) => row.source,
            Value: ({ row }) => <StatusChip label={sourceLabel(row.source)} tone={row.source === "OPERATOR_CASE" ? "info" : "neutral"} size="x-small" />,
        },
        {
            key: "scheduledAt",
            label: "Scheduled",
            sortKey: "scheduledAt",
            value: (row) => row.scheduledAt,
            Value: ({ row }) => <ThemedText style={{ fontSize: "12px" }}>{formatDateTime(row.scheduledAt)}</ThemedText>,
        },
        {
            key: "nextRunAt",
            label: "Next run",
            sortKey: "nextRunAt",
            value: (row) => row.nextRunAt,
            Value: ({ row }) => (
                <ThemedView style={{ gap: "2px" }}>
                    <ThemedText style={{ fontSize: "12px", fontWeight: row.isOverdue ? 700 : 400 }}>{formatDateTime(row.nextRunAt)}</ThemedText>
                    {row.attempts > 0 && <ThemedText style={{ fontSize: "10px", opacity: 0.55 }}>{row.attempts} {t("attempts")}</ThemedText>}
                </ThemedView>
            ),
        },
        {
            key: "lastRunAt",
            label: "Last run",
            sortKey: "lastRunAt",
            value: (row) => row.lastRunAt ?? "",
            Value: ({ row }) => <ThemedText style={{ fontSize: "12px" }}>{formatDateTime(row.lastRunAt)}</ThemedText>,
        },
        {
            key: "lastResult",
            label: "Result",
            value: (row) => row.lastResult ?? row.lastError ?? "",
            Value: ({ row }) => (
                <ThemedView style={{ gap: "2px", maxWidth: "220px" }}>
                    {row.lastResult && <StatusChip label={row.lastResult} tone={statusTone(row.lastResult)} size="x-small" />}
                    {row.lastError && <ThemedText style={{ fontSize: "10px", opacity: 0.65 }}>{row.lastError}</ThemedText>}
                    {!row.lastResult && !row.lastError && <ThemedText style={{ fontSize: "11px", opacity: 0.5 }}>—</ThemedText>}
                </ThemedView>
            ),
        },
        {
            key: "actions",
            label: "Actions",
            sortable: false,
            Value: ({ row }) => (
                <ThemedView style={{ flexDirection: "row", gap: "6px", alignItems: "center", flexWrap: "wrap" }}>
                    <VBtn size="small" variant="text" prependIcon="mdi-eye-outline" onClick={() => void openDetail(row)}>
                        {t("View")}
                    </VBtn>
                    <VBtn
                        size="small"
                        variant="tonal"
                        disabled={!canAct.value || !row.canRunNow || actionLoading.value}
                        onClick={() => openAction("run-now", row)}
                    >
                        {t("Run now")}
                    </VBtn>
                    <VBtn
                        size="small"
                        variant="tonal"
                        color="warning"
                        disabled={!canAct.value || !row.canCancel || actionLoading.value}
                        onClick={() => openAction("cancel", row)}
                    >
                        {t("Cancel")}
                    </VBtn>
                    <VBtn
                        size="small"
                        variant="tonal"
                        color="primary"
                        disabled={!canAct.value || !row.canRetry || actionLoading.value}
                        onClick={() => openAction("retry", row)}
                    >
                        {t("Retry")}
                    </VBtn>
                </ThemedView>
            ),
        },
    ];

    return () => (
        <ScreenContainer>
            <ThemedView style={{ gap: "18px" }}>
                <PageHeader
                    title={t("Gateway Inquiry Schedule")}
                    end={() => (
                        <ThemedView style={{ flexDirection: "row", gap: "10px", flexWrap: "wrap" }}>
                            <VBtn variant="text" prependIcon="mdi-arrow-left" onClick={() => void router.push({ name: "OperatorCases" })}>
                                {t("Operator Cases")}
                            </VBtn>
                            <VBtn variant="tonal" prependIcon="mdi-refresh" loading={summaryLoading.value} onClick={refreshAll}>
                                {t("Refresh")}
                            </VBtn>
                        </ThemedView>
                    )}
                />

                <VAlert type="info" variant="tonal">
                    {t("Schedules are created when an operator requests a gateway status inquiry. The platform poll worker performs the inquiry and updates the schedule status.")}
                </VAlert>

                <ThemedView style={{ display: "grid", gridTemplateColumns: "repeat(auto-fit, minmax(140px, 1fr))", gap: "10px" }}>
                    {cards.value.map((item) => (
                        <VCard key={item.key} variant="tonal">
                            <VCardText style={{ display: "flex", flexDirection: "column", gap: "4px", padding: "12px" }}>
                                <ThemedText style={{ fontSize: "11px", opacity: 0.62 }}>{item.label}</ThemedText>
                                <ThemedText type="defaultSemiBold" style={{ fontSize: "20px" }}>{item.value}</ThemedText>
                            </VCardText>
                        </VCard>
                    ))}
                </ThemedView>

                <ApiTable<GatewayInquirySchedule>
                    title={t("Gateway Inquiry Schedule")}
                    url={urlsMap.gatewayInquiries}
                    showNumber={true}
                    xlsx={true}
                    localSearch={false}
                    numberOfItemsPerPage={pageSize.value}
                    setNumberOfItemsPerPage={(value) => (pageSize.value = value)}
                    searchValue={search.value}
                    setSearchValue={(value) => {
                        search.value = value;
                        onSearch();
                    }}
                    headers={headers}
                    rowColor={(row) => (row.isOverdue ? theme.current.value.colors.warning : undefined)}
                    apiDataExtractor={(data) => {
                        const payload = data as { schedules?: GatewayInquirySchedule[]; rows?: GatewayInquirySchedule[] };
                        return payload.schedules ?? payload.rows ?? [];
                    }}
                    apiTotalExtractor={(data) => Number((data as { total?: number }).total ?? 0)}
                    onData={(_rows, nextTotal) => {
                        total.value = nextTotal;
                    }}
                    setRefreshHook={(hook) => {
                        refreshHook.value = hook as typeof refreshHook.value;
                    }}
                    clearRefreshHook={() => {
                        refreshHook.value = null;
                    }}
                    onRefresh={(props, refresh) => {
                        void refresh({
                            queryParams: {
                                page: props.page,
                                pageSize: pageSize.value,
                                ...(search.value ? { search: search.value } : {}),
                                ...buildFilterQuery(filterDefinitions, filters.value),
                                ...(props.sortKey ? { sortKey: props.sortKey, sortDirection: props.sortDirection } : {}),
                            },
                        });
                    }}
                    TopSlot={() => (
                        <TableFilters
                            filters={filterDefinitions}
                            values={filters.value}
                            total={total.value}
                            onChange={onFiltersChanged}
                            onClear={onFiltersCleared}
                        />
                    )}
                />
            </ThemedView>

            <VDialog modelValue={actionMode.value !== null} onUpdate:modelValue={(value: boolean) => !value && closeAction()} maxWidth="520px">
                <VCard>
                    <VCardText style={{ display: "flex", flexDirection: "column", gap: "14px" }}>
                        <ThemedText type="defaultSemiBold" style={{ fontSize: "18px" }}>{actionTitle.value}</ThemedText>
                        <ThemedText style={{ fontSize: "12px", opacity: 0.7 }}>{actionDescription.value}</ThemedText>
                        {actionRow.value && (
                            <ThemedView style={{ gap: "3px", padding: "10px", borderRadius: "10px", background: "rgba(100,116,139,0.08)" }}>
                                <ThemedText style={{ fontSize: "12px", fontWeight: 700 }}>{actionRow.value.caseRef || actionRow.value.operatorCaseId}</ThemedText>
                                <ThemedText style={{ fontSize: "11px", opacity: 0.65 }}>{actionRow.value.attemptReference} · {actionRow.value.gatewayName || actionRow.value.gatewayCode}</ThemedText>
                            </ThemedView>
                        )}
                        <VTextarea
                            label={actionMode.value === "cancel" ? t("Cancellation reason") : t("Reason (optional)")}
                            modelValue={actionReason.value}
                            onUpdate:modelValue={(value: string) => (actionReason.value = value)}
                            rows={3}
                            hint={actionMode.value === "cancel" ? t("At least 3 characters.") : undefined}
                            persistentHint={actionMode.value === "cancel"}
                        />
                        <ThemedView style={{ flexDirection: "row", justifyContent: "flex-end", gap: "10px" }}>
                            <VBtn variant="text" onClick={closeAction}>{t("Close")}</VBtn>
                            <VBtn
                                color={actionMode.value === "cancel" ? "warning" : "primary"}
                                loading={actionLoading.value}
                                disabled={actionMode.value === "cancel" && actionReason.value.trim().length < 3}
                                onClick={() => void submitAction()}
                            >
                                {actionMode.value === "cancel" ? t("Cancel inquiry") : actionMode.value === "retry" ? t("Retry inquiry") : t("Run now")}
                            </VBtn>
                        </ThemedView>
                    </VCardText>
                </VCard>
            </VDialog>

            <VDialog modelValue={detailOpen.value} onUpdate:modelValue={(value: boolean) => (detailOpen.value = value)} maxWidth="760px" scrollable>
                <VCard>
                    <VCardText style={{ display: "flex", flexDirection: "column", gap: "14px" }}>
                        <ThemedView style={{ flexDirection: "row", justifyContent: "space-between", gap: "10px", alignItems: "center" }}>
                            <ThemedText type="defaultSemiBold" style={{ fontSize: "18px" }}>{t("Gateway inquiry detail")}</ThemedText>
                            <VBtn icon="mdi-close" variant="text" onClick={() => (detailOpen.value = false)} />
                        </ThemedView>
                        {detailLoading.value ? (
                            <ThemedText style={{ opacity: 0.65 }}>{t("Loading")}</ThemedText>
                        ) : detail.value ? (
                            <>
                                <ThemedView style={{ display: "grid", gridTemplateColumns: "repeat(auto-fit, minmax(190px, 1fr))", gap: "10px" }}>
                                    {[
                                        [t("Status"), statusLabel(detail.value.schedule.status)],
                                        [t("Source"), sourceLabel(detail.value.schedule.source)],
                                        [t("Case"), detail.value.schedule.caseRef || detail.value.schedule.operatorCaseId || "—"],
                                        [t("Attempt"), detail.value.schedule.attemptReference || "—"],
                                        [t("Merchant"), detail.value.schedule.merchantName || "—"],
                                        [t("Gateway"), detail.value.schedule.gatewayName || detail.value.schedule.gatewayCode || "—"],
                                        [t("Scheduled"), formatDateTime(detail.value.schedule.scheduledAt)],
                                        [t("Next run"), formatDateTime(detail.value.schedule.nextRunAt)],
                                        [t("Last run"), formatDateTime(detail.value.schedule.lastRunAt)],
                                        [t("Attempts"), String(detail.value.schedule.attempts)],
                                        [t("Last result"), detail.value.schedule.lastResult || "—"],
                                        [t("Last error"), detail.value.schedule.lastError || "—"],
                                        [t("Scheduled by"), detail.value.schedule.scheduledByEmail || "—"],
                                        [t("Cancelled by"), detail.value.schedule.cancelledByEmail || "—"],
                                        [t("Cancel reason"), detail.value.schedule.cancelReason || "—"],
                                    ].map(([label, value]) => (
                                        <VCard key={label} variant="tonal">
                                            <VCardText style={{ display: "flex", flexDirection: "column", gap: "3px", padding: "10px" }}>
                                                <ThemedText style={{ fontSize: "10px", opacity: 0.6, textTransform: "uppercase" }}>{label}</ThemedText>
                                                <ThemedText style={{ fontSize: "12px", fontWeight: 600 }}>{value}</ThemedText>
                                            </VCardText>
                                        </VCard>
                                    ))}
                                </ThemedView>
                                <ThemedText type="defaultSemiBold">{t("Schedule audit trail")}</ThemedText>
                                {detail.value.auditTrail.length === 0 ? (
                                    <ThemedText style={{ fontSize: "12px", opacity: 0.6 }}>{t("No audit entries yet.")}</ThemedText>
                                ) : (
                                    detail.value.auditTrail.map((entry) => (
                                        <ThemedView key={entry.id} style={{ gap: "3px", borderBottom: "1px solid rgba(100,116,139,0.12)", paddingBottom: "7px" }}>
                                            <ThemedView style={{ flexDirection: "row", justifyContent: "space-between", gap: "10px" }}>
                                                <ThemedText style={{ fontSize: "12px", fontWeight: 700 }}>{entry.action.replaceAll("_", " ")}</ThemedText>
                                                <ThemedText style={{ fontSize: "10px", opacity: 0.55 }}>{formatDateTime(entry.createdAt)}</ThemedText>
                                            </ThemedView>
                                            <ThemedText style={{ fontSize: "11px", opacity: 0.65 }}>
                                                {entry.actor?.email || entry.role}
                                            </ThemedText>
                                        </ThemedView>
                                    ))
                                )}
                            </>
                        ) : null}
                    </VCardText>
                </VCard>
            </VDialog>
        </ScreenContainer>
    );
});

