/* Modern Drawer */
.modern-drawer {
    transition: all 0.3s cubic-bezier(0.4, 0, 0.2, 1);
}

/* ThemedView Animations */
.themed-view-animated {
    transition: all 0.3s cubic-bezier(0.4, 0, 0.2, 1);
}

/* Smooth page transitions */
.fade-enter-active,
.fade-leave-active {
    transition: opacity 0.3s ease;
}

.fade-enter-from,
.fade-leave-to {
    opacity: 0;
}

/* Enhanced scrollbar for drawer */
.modern-drawer ::-webkit-scrollbar {
    width: 8px;
}

.modern-drawer ::-webkit-scrollbar-track {
    background: rgba(0, 0, 0, 0.02);
    border-radius: 4px;
}

.modern-drawer ::-webkit-scrollbar-thumb {
    background: rgba(0, 0, 0, 0.2);
    border-radius: 4px;
    transition: background 0.2s ease;
}

.modern-drawer ::-webkit-scrollbar-thumb:hover {
    background: rgba(0, 0, 0, 0.3);
}

.v-theme--dark .modern-drawer ::-webkit-scrollbar-track {
    background: rgba(255, 255, 255, 0.02);
}

.v-theme--dark .modern-drawer ::-webkit-scrollbar-thumb {
    background: rgba(255, 255, 255, 0.2);
}

.v-theme--dark .modern-drawer ::-webkit-scrollbar-thumb:hover {
    background: rgba(255, 255, 255, 0.3);
}

/* Smooth animations for list items */
@keyframes slideIn {
    from {
        opacity: 0;
        transform: translateX(-10px);
    }
    to {
        opacity: 1;
        transform: translateX(0);
    }
}

.route-item {
    animation: slideIn 0.3s ease-out;
}

/* Enhanced focus states */
.route-item:focus-visible {
    outline: 2px solid rgba(0, 0, 0, 0.1);
    outline-offset: 2px;
    border-radius: 14px;
}

.v-theme--dark .route-item:focus-visible {
    outline: 2px solid rgba(255, 255, 255, 0.1);
}

/* Smooth gradient transitions */
