            isMaker: !!payload?.userInfo?.isMaker,
            isChecker: !!payload?.userInfo?.isChecker,
        },
    });

    const loginWithGoogle = async () => {
        error.value = null;
        loading.value = true;
        try {
            const response = await api.post(urlsMap.authGoogle, { redirectUri: location.href });
