            return;
        }
        error.value = null;
        loading.value = true;
        try {
            if (challengeId.value) {
                const response = await api.post(urlsMap.authMfaVerify, {
                    challengeId: challengeId.value,
                    code: mfaCode.value.trim(),
                });
                const session = buildSession(response.data?.data ?? response.data ?? {});
