            if (!session.token) {
                throw new Error("missing token");
            }
            setUserState(session);
            await router.push({ name: "Dashboard" });
        } catch (e) {
            error.value = extractApiErrorMessage(e);
        } finally {
            loading.value = false;
        }
    };

