body,
#app {
    padding: 0px;
    margin: 0px;
    height: 100%;
}

/*
 * The mount point is a plain full-size surface.
 *
 * A global `transform: scale()` here used to shrink the whole app to 0.9, but a
 * transformed ancestor becomes the containing block for `position: fixed`
 * children, so Vuetify's app bar, navigation drawer, dialogs and snackbars were
 * mis-positioned (and the top-left transform origin left a gap in the RTL
 * layout). Scaling that way is not compatible with the app shell; use Vuetify
 * density props (`density="compact"`) where a tighter layout is wanted.
 */
#app {
    width: 100%;
    height: 100%;
}

