::-webkit-scrollbar {
    width: 6px; /* For vertical scrollbars */
    height: 6px; /* For horizontal scrollbars */
}

/* Track */
::-webkit-scrollbar-track {
    background: transparent;
}

/* Handle */
::-webkit-scrollbar-thumb {
    background-color: rgba(100, 100, 100, 0.4);
    border-radius: 4px;
}

/* Handle on hover */
::-webkit-scrollbar-thumb:hover {
    background-color: rgba(100, 100, 100, 0.7);
}

.v-theme--dark ::-webkit-scrollbar-thumb {
    background-color: rgba(200, 200, 200, 0.3);
}

.v-theme--dark ::-webkit-scrollbar-thumb:hover {
    background-color: rgba(200, 200, 200, 0.5);
}

.required-field .v-label::after {
    content: " *";
    color: red;
}

* {
    scrollbar-width: thin !important;
    font-family: "IBM Plex Sans", "IBM Plex Sans Arabic", system-ui, sans-serif;
    font-optical-sizing: auto;
    letter-spacing: 0;
    scrollbar-color: rgba(100, 100, 100, 0.4) transparent;
}

/* Arabic uses IBM Plex Sans Arabic; Latin uses IBM Plex Sans. */
[dir="rtl"] *,
[dir="rtl"] {
    font-family: "IBM Plex Sans Arabic", "IBM Plex Sans", system-ui, sans-serif;
    letter-spacing: 0;
}

.v-theme--dark * {
    scrollbar-color: rgba(200, 200, 200, 0.3) transparent;
}
html {
    overflow-y: auto;
}

.tiny-autocomplete {
    font-size: 0.75rem; /* reduce font globally */
}

.tiny-autocomplete .v-field__input {
    font-size: 0.75rem;
    min-height: 32px; /* reduce height */
    padding-top: 2px;
    padding-bottom: 2px;
}

.tiny-autocomplete .v-field__label {
    font-size: 0.7rem;
}

.show-in-print {
    display: none;
}
.printable-header {
    page-break-after: auto !important;
    page-break-inside: avoid !important;
    orphans: 3 !important;
    widows: 3 !important;
}

@media print {
    .print-hide {
        display: none !important;
