                                <VCardText style={{ display: "flex", flexDirection: "column", gap: "8px" }}>
                                    <ThemedText type="defaultSemiBold">{t("Treasury Cover")}</ThemedText>
                                    {sideRow("Treasury Balance", data.value?.sides?.treasury)}

