                     props.headers[0] = {
                         value: (_, index) => String(index + 1 + skip.value),
                         key: "__no",
                         label: "No",
                         minWidth: true,
                         sortable: false,
                     };
                 }
             }
             return (
                 <ThemedView
                     style={{
                         flexDirection: "column",
-                        gap: "16px",
-                        padding: isMobile.value ? "16px" : "24px",
-                        backgroundColor: isDark ? colors.surface : "#ffffff",
-                        borderRadius: "12px",
