         const update = (value: Date[] | Date | null) => {
             const dates = (Array.isArray(value) ? value : value ? [value] : []).filter(
                 (date): date is Date => date instanceof Date && !Number.isNaN(date.getTime()),
             );
             if (dates.length === 0) {
                 props.onChange(undefined);
