             evidenceJson: null,
             canSubmitEvidence: false,
             evidenceBlockedReason: null,
         };
         evidenceReference.value = "";
         evidenceDocumentUrl.value = "";
         evidenceNotes.value = "";
         evidenceChecklist.value = {};
         detailsOpen.value = true;
