             const escape = (value: unknown) => `"${String(value ?? "").replaceAll('"', '""')}"`;
             const rows: Array<[string, unknown]> = [
                 ["checked_at", snapshot.checkedAt ?? ""],
                 ["ok", snapshot.ok === true],
                 ["drift", snapshot.drift ?? "0"],
                 ["currency", snapshot.currency ?? "LYD"],
