             return;
         }
         let tiers: unknown = [];
         if (form.model === "TIERED" || form.model === "MIXED") {
             try {
                 tiers = JSON.parse(form.tiers || "[]");
             } catch {
                 commissionError.value = t("Tiers must be a valid JSON array.");
                 return;
