     specVersion: string;
     markdown: string;
     vocabulary: Record<string, string[]>;
 };

 type VerificationIssue = {
     path: string;
     code: string;
     message: string;
     aiFixHint: string;
 };

 type LayerResult = {
     layer: number;
     name: string;
     passed: boolean;
     errorCount: number;
     warningCount: number;
 };

 type VectorRequest = {
     method: string;
     url: string;
     headers: Record<string, string>;
     body: string;
 };

 type VectorResult = {
     name: string;
     phase: string;
     passed: boolean;
     status?: string;
     extractions: Record<string, unknown>;
     requests: VectorRequest[];
     errors: VerificationIssue[];
 };

 type VerificationSummary = {
     gatewayCode: string | null;
     railCode: string | null;
     collectionMode: string | null;
     vectorCount: number;
     passedVectors: number;
     flowPhases: string[];
     errorCount: number;
     warningCount: number;
 };

 type RequiredCredential = {
     key: string;
     is_secret: boolean;
     encoding?: string;
     description?: string;
     type: string;
 };

 type CollisionInfo = {
     gatewayExists: boolean;
     railCodeExists: boolean;
     versionCount: number;
 };

 type VerificationReport = {
     valid: boolean;
     specVersion: string | null;
     layers: LayerResult[];
     summary: VerificationSummary;
     requiredCredentials: RequiredCredential[];
     vectorResults: VectorResult[];
     errors: VerificationIssue[];
     warnings: VerificationIssue[];
     collision?: CollisionInfo;
     aiRepairPrompt?: string;
 };

 type CredentialCheck = {
     status: string;
     method?: string;
     reason?: string;
 };

 type ImportResponse = {
     gatewayId: string;
     gatewayCode: string;
     gatewayVersionId: string;
     versionNumber: number;
     versionState: string;
     railId: string;
     railCode: string;
     railRouteId: string;
     credentialSetId: string;
     counts: Record<string, unknown>;
     verification: VerificationReport;
     credentialCheck?: CredentialCheck;
     nextStep: string;
 };

 const formatValue = (value: unknown): string => {
     if (value === null || value === undefined) {
         return "";
     }
     if (typeof value === "string") {
         return value;
     }
     if (typeof value === "number" || typeof value === "boolean") {
         return String(value);
     }
     try {
         return JSON.stringify(value, null, 2);
     } catch {
         return String(value);
     }
 };

 const prettyBody = (body: string): string => {
     if (!body) {
         return "";
     }
     try {
         return JSON.stringify(JSON.parse(body), null, 2);
     } catch {
         return body;
     }
 };

 const monoStyle = {
     fontFamily: "ui-monospace, SFMono-Regular, Menlo, Consolas, monospace",
     fontSize: "12px",
     lineHeight: 1.55,
     whiteSpace: "pre-wrap",
     wordBreak: "break-word",
     direction: "ltr",
     textAlign: "left",
     margin: 0,
     padding: "10px",
     borderRadius: "8px",
     background: "rgba(100,116,139,0.12)",
     overflowX: "auto",
 } as const;

 type RepairPromptErrorShape = {
     response?: {
         data?: {
             details?: { aiRepairPrompt?: unknown };
             data?: { details?: { aiRepairPrompt?: unknown } };
             aiRepairPrompt?: unknown;
         };
     };
     aiRepairPrompt?: unknown;
 };

 const extractRepairPrompt = (error: unknown): string | null => {
     const shape = error as RepairPromptErrorShape | null | undefined;
     const data = shape?.response?.data;
     const candidates: unknown[] = [
         data?.details?.aiRepairPrompt,
         data?.data?.details?.aiRepairPrompt,
         data?.aiRepairPrompt,
         shape?.aiRepairPrompt,
     ];
     for (const candidate of candidates) {
         if (typeof candidate === "string" && candidate.trim()) {
             return candidate;
         }
     }
     return null;
 };

