                         .map(escape)
                         .join(","),
                 ),
             ];
             await xlsxUIPipeline.downloadXlsxFromCsvLines({
                 title: `gateways-${new Date().toISOString().slice(0, 10)}.xlsx`,
                 lines,
             });
             showSnackBar({
                 type: payload.truncated ? "warning" : "success",
