             for (const [status, count] of Object.entries(snapshot.byStatus ?? {})) rows.push([`status.${status}.count`, count]);
             for (const [kind, count] of Object.entries(snapshot.byKind ?? {})) rows.push([`kind.${kind}.count`, count]);
