             const payload = response.data?.data ?? response.data ?? {};
             const detail = payload.rail ?? payload;
             fields.value = (detail.fields ?? []).map(toPublicField);
         } catch (e) {
             showSnackBar({ type: "error", message: extractApiErrorMessage(e) });
