     const railFieldChecklistComplete = computed(() => !showChecklists || RAIL_FIELD_CHECKS.every((check) => railFieldChecklist.value[check.key] === true));

     const persistFields = async (next: PublicField[]): Promise<void> => {
         if (!selected.value) {
             return;
