 @supports (backdrop-filter: blur(10px)) {
     .modern-drawer,
     .account-actions-trigger,
     .menu-toggle-button {
         backdrop-filter: blur(20px);
         -webkit-backdrop-filter: blur(20px);
     }
 }

 /* Loading state animations */
 @keyframes pulse {
     0%,
     100% {
         opacity: 1;
     }
     50% {
         opacity: 0.6;
     }
 }

 /* Responsive improvements */
 @media (max-width: 768px) {
     .account-actions-trigger {
         min-width: auto !important;
         padding: 6px 12px !important;
     }

     .modern-drawer {
         width: 280px !important;
     }
 }

 html,
 body,
 #app {
     padding: 0px;
     margin: 0px;
     height: 100%;
 }

 /*
  * The mount point is a plain full-size surface. A global `transform: scale()`
  * here would turn #app into the containing block for `position: fixed`
  * children, mis-positioning the app bar/drawers/dialogs and causing horizontal
  * overflow. Density is controlled per component instead.
  */
 #app {
     width: 100%;
     height: 100%;
 }

 // .drawer-width {
 //     transition: all 0.5s;
 // }
 ::-webkit-scrollbar {
     width: 6px; /* For vertical scrollbars */
     height: 6px; /* For horizontal scrollbars */
 }

 /* Track */
 ::-webkit-scrollbar-track {
     background: transparent;
 }

 /* Handle */
 ::-webkit-scrollbar-thumb {
     background-color: rgba(100, 100, 100, 0.4);
     border-radius: 4px;
 }

 /* Handle on hover */
 ::-webkit-scrollbar-thumb:hover {
     background-color: rgba(100, 100, 100, 0.7);
 }

 .v-theme--dark ::-webkit-scrollbar-thumb {
     background-color: rgba(200, 200, 200, 0.3);
 }

 .v-theme--dark ::-webkit-scrollbar-thumb:hover {
     background-color: rgba(200, 200, 200, 0.5);
 }

 .required-field .v-label::after {
     content: " *";
     color: red;
 }

 * {
     scrollbar-width: thin !important;
-    font-family: "IBM Plex Sans", "IBM Plex Sans Arabic", system-ui, sans-serif;
+    font-family: "Plus Jakarta Sans", "Cairo", system-ui, sans-serif;
     font-optical-sizing: auto;
     letter-spacing: 0;
     scrollbar-color: rgba(100, 100, 100, 0.4) transparent;
 }

 /* Arabic uses IBM Plex Sans Arabic; Latin uses IBM Plex Sans. */
 [dir="rtl"] *,
 [dir="rtl"] {
-    font-family: "IBM Plex Sans Arabic", "IBM Plex Sans", system-ui, sans-serif;
+    font-family: "Cairo", "Plus Jakarta Sans", system-ui, sans-serif;
     letter-spacing: 0;
 }

 .v-theme--dark * {
     scrollbar-color: rgba(200, 200, 200, 0.3) transparent;
 }
 html {
     overflow-y: auto;
 }

 .tiny-autocomplete {
     font-size: 0.75rem; /* reduce font globally */
 }

 .tiny-autocomplete .v-field__input {
     font-size: 0.75rem;
     min-height: 32px; /* reduce height */
     padding-top: 2px;
     padding-bottom: 2px;
 }

 .tiny-autocomplete .v-field__label {
     font-size: 0.7rem;
 }

 .show-in-print {
     display: none;
 }
 .printable-header {
     page-break-after: auto !important;
     page-break-inside: avoid !important;
     orphans: 3 !important;
     widows: 3 !important;
 }

 @media print {
     .print-hide {
         display: none !important;
     }

     html,
     body {
         margin: 0 !important;
         padding: 0 !important;
         color: black !important;
     }
     .show-in-print {
         display: inherit;
     }
 }
 @page {
     size: A4;
     margin-top: 1cm !important;
     margin-bottom: 1cm !important;
 }

 /* ---------------------------------------------------------------------------
  * Payer (checkout) surface — one focused column, no app chrome.
  * ------------------------------------------------------------------------- */
 .pg-checkout {
     min-height: 100dvh;
     display: flex;
     flex-direction: column;
     align-items: center;
     justify-content: center;
     gap: 12px;
     padding: 24px 16px 60px;
-    background: linear-gradient(170deg, #f4f7fb 0%, #e6eefb 55%, #e7f6f3 100%);
+    background: var(--pg-bg-canvas);
 }

 .pg-checkout__title {
     font-size: 17px;
     font-weight: 700;
 }

 @media (max-width: 600px) {
     .pg-checkout {
         justify-content: flex-start;
         padding: 16px 12px 48px;
     }
 }

