     border-radius: 14px;
 }

 .v-theme--dark .route-item:focus-visible {
     outline: 2px solid rgba(255, 255, 255, 0.1);
 }

 /* Smooth gradient transitions */
 @keyframes gradientShift {
     0%,
     100% {
         background-position: 0% 50%;
     }
     50% {
         background-position: 100% 50%;
     }
 }

