  direction: ltr;
  unicode-bidi: embed;
}

.pg-muted {
  color: var(--pg-ink-muted);
}

.pg-faint {
  color: var(--pg-ink-faint);
}

.pg-shell-divider {
  border-color: var(--pg-border-subtle) !important;
}

.v-card {
  box-shadow: var(--pg-shadow-xs) !important;
