import { defineComponent, type PropType, type VNodeChild } from "vue";

export type BadgeTone = "success" | "warning" | "danger" | "info" | "neutral";

const STATUS_TO_TONE: Record<string, BadgeTone> = {
    LIVE: "success",
    ACTIVE: "success",
    SUCCEEDED: "success",
    APPROVED: "success",
    EXECUTED: "success",
    VERIFIED: "success",
    HEALTHY: "success",
    CLEAR: "success",
    CLEAN: "success",
    ACCEPTED: "success",
    MATCHED: "success",
    COMPLETE: "success",
    COMPLETED: "success",
