    CONFIRMED: "success",
    WON: "success",
    RELEASED: "success",
    DELIVERED: "success",
    SETTLED: "success",
    PROCESSED: "success",
    RESOLVED: "success",
    FALSE_POSITIVE: "neutral",

    PENDING: "warning",
    PENDING_REVIEW: "warning",
    PENDING_CHECKER: "warning",
    PENDING_APPROVAL: "warning",
    IN_REVIEW: "warning",
