                                {props.title}
                            </h3>
                            {props.subtitle && (
                                <p style={{ fontSize: "12.5px", color: "var(--pg-ink-muted)", margin: "3px 0 0 0" }}>
                                    {props.subtitle}
                                </p>
                            )}
                        </div>
                        <VBtn icon="mdi-close" variant="text" size="x-small" onClick={close} aria-label={t("Close")} />
                    </div>
                    <div
                        style={{
                            padding: "20px",
                            overflowY: "auto",
                            display: "flex",
                            flexDirection: "column",
                            gap: "16px",
