                [key: string]: any;
            },
        );
        const editingCells = ref(
            {} as {
                [cellKey: string]: any;
            },
        );
        const loadingCells = ref(
            {} as {
                [cellKey: string]: any;
            },
        );
        const validCells = ref(
            {} as {
                [cellKey: string]: any;
            },
        );

        const errorCells = ref(
            {} as {
                [cellKey: string]: any;
