import re, pathlib

ROOT = pathlib.Path('/home/selmotamed/payment-gateway-monolith/admin-front/src/pages')
DIALOG_OPEN = re.compile(r'<VDialog\b')
TITLE_PATTERNS = [
    re.compile(r'<VCardTitle\b[^>]*>(.*?)</VCardTitle>', re.S),
    re.compile(r'<ThemedText\b[^>]*type="defaultSemiBold"[^>]*>(.*?)</ThemedText>', re.S),
    re.compile(r'<ThemedText\b[^>]*type=\{"defaultSemiBold"\}[^>]*>(.*?)</ThemedText>', re.S),
    re.compile(r'<h[12]\b[^>]*>(.*?)</h[12]>', re.S),
]

def find_close(text, start):
    depth = 0
    pos = start
    while True:
        m = re.search(r'</?VDialog\b', text[pos:])
        if not m:
            return -1
        abs_pos = pos + m.start()
        if text[abs_pos:abs_pos+2] == '</':
            depth -= 1
            if depth == 0:
                return abs_pos
        else:
            depth += 1
        pos = abs_pos + 1

def extract_balanced_expr(text, start):
    """start points at '{'; return (expr_without_braces, end_after_brace)."""
    depth = 0
    i = start
    in_str = None
    esc = False
    while i < len(text):
        ch = text[i]
        if in_str:
            if esc:
                esc = False
            elif ch == '\\':
                esc = True
            elif ch == in_str:
                in_str = None
        else:
            if ch in ('"', "'", '`'):
                in_str = ch
            elif ch == '{':
                depth += 1
            elif ch == '}':
                depth -= 1
                if depth == 0:
                    return text[start+1:i], i+1
        i += 1
    return None, -1

def get_prop(open_tag, name):
    idx = open_tag.find(name)
    if idx < 0:
        return None
    eq = open_tag.find('=', idx)
    if eq < 0:
        return None
    i = eq + 1
    while i < len(open_tag) and open_tag[i].isspace():
        i += 1
    if i >= len(open_tag):
        return None
    if open_tag[i] == '{':
        expr, end = extract_balanced_expr(open_tag, i)
        return ('expr', expr, end)
    if open_tag[i] in ('"', "'"):
        quote = open_tag[i]
        end = open_tag.find(quote, i+1)
        return ('str', open_tag[i+1:end], end+1)
    return None

def title_expression(raw):
    raw = raw.strip()
    if raw.startswith('{') and raw.endswith('}'):
        inner = raw[1:-1].strip()
        # Strip JSX whitespace and comments
        return inner
    clean = re.sub(r'<[^>]+>', '', raw).strip()
    clean = re.sub(r'\s+', ' ', clean)
    if not clean:
        return '"Details"'
    return '"' + clean.replace('"', '\\"') + '"'

def transform(text):
    while True:
        m = DIALOG_OPEN.search(text)
        if not m:
            break
        start = m.start()
        open_end = text.find('>', m.end())
        if open_end < 0:
            break
        # handle self-closing VDialog (should not happen, but avoid loop)
        if text[open_end-1] == '/':
            text = text[:start] + text[open_end+1:]
            continue
        close_start = find_close(text, open_end+1)
        if close_start < 0:
            break
        close_end = text.find('>', close_start) + 1
        open_tag = text[start:open_end+1]
        inner = text[open_end+1:close_start]

        model = get_prop(open_tag, 'modelValue')
        update = get_prop(open_tag, 'onUpdate:modelValue')
        persistent = get_prop(open_tag, 'persistent')
        width = get_prop(open_tag, 'maxWidth')

        title = None
