            mm = re.search(r'(\d+)', w)
            if mm:
                px = int(mm.group(1))
                size = 'sm' if px <= 520 else 'md' if px <= 720 else 'lg'

        # Strip one outer SurfaceCard/VCard wrapper and one body wrapper.
        inner = inner.strip()
        for card_tag in ('VCard', 'SurfaceCard'):
