import re
from pathlib import Path
ROOT=Path('/home/selmotamed/payment-gateway-monolith/admin-front/src/pages')
changed=[]
for path in ROOT.rglob('*.tsx'):
    s=path.read_text()
    if '<VChip' not in s:
        continue
    out=s.replace('</VChip>','</MetaPill>').replace('<VChip','<MetaPill')
    def fix_import(m):
        names=[n.strip() for n in m.group(1).split(',') if n.strip()]
        names=[n for n in names if n!='VChip']
        if not names: return ''
        return 'import { '+', '.join(names)+' } from "vuetify/components";'
    out=re.sub(r'import\s*\{([^}]*)\}\s*from\s*"vuetify/components";',fix_import,out)
    if 'ui/MetaPill' not in out:
        imports=list(re.finditer(r'^import[\s\S]*?;\s*$',out,re.M))
        imp='import { MetaPill } from "@/components/ui/MetaPill";'
        if imports:
            end=imports[-1].end(); out=out[:end]+'\n'+imp+out[end:]
        else:
            out=imp+'\n'+out
    path.write_text(out)
    changed.append(str(path))
print('changed',len(changed))
