    display: flex;
    align-items: center;
    gap: 10px;
    min-width: 0;
    margin-inline-start: 4px;
}

.pg-app-bar__title {
    font-size: 15px;
    font-weight: 800;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}

.pg-spacer {
    flex: 1 1 auto;
}

.pg-user-btn {
    text-transform: none;
    letter-spacing: 0;
    padding-inline: 8px;
}

.pg-user-btn__name {
    margin-inline-start: 8px;
    font-size: 13px;
    font-weight: 700;
    max-width: 160px;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
}

.pg-avatar {
    background: var(--pg-ink-primary);
    color: white;
    font-weight: 800;
}

.pg-drawer {
    border-inline-end: 1px solid var(--fintech-border);
    display: flex;
    flex-direction: column;
    height: 100%;
    max-height: 100dvh;
    overflow: hidden;
}

.pg-drawer .v-navigation-drawer__content {
    display: flex;
    flex-direction: column;
    height: 100%;
    min-height: 0;
    overflow: hidden;
}

