for d in merchant-front checkout-front; do cat > $d/src/components/StatusChip/index.tsx <<'TSX'
import { defineComponent, type PropType } from "vue";
import { StatusBadge, type BadgeTone } from "@/components/ui/StatusBadge";

export type StatusTone = "success" | "error" | "warning" | "info" | "primary" | "neutral";
export type StatusChipProps = {
    label: string;
    tone?: StatusTone;
    size?: "x-small" | "small" | "default";
    variant?: "tonal" | "flat" | "outlined" | "text";
};

const toBadgeTone = (tone: StatusTone | undefined): BadgeTone => {
    if (tone === "error") return "danger";
    if (tone === "primary") return "info";
    return tone ?? "neutral";
};

export const StatusChip = defineComponent({
    name: "StatusChip",
    props: {
        label: { type: String, required: true },
        tone: { type: String as PropType<StatusTone>, default: "neutral" },
        size: { type: String, default: "small" },
        variant: { type: String, default: "tonal" },
    },
    setup(props) {
        return () => (
            <StatusBadge status={String(props.label ?? "")} label={String(props.label ?? "")} toneOverride={toBadgeTone(props.tone)} />
        );
    },
});

export default StatusChip;
TSX
cat > $d/src/components/MoneyText/index.tsx <<'TSX'
import { defineComponent, type PropType, type StyleValue } from "vue";
import { MoneyDisplay } from "@/components/ui/MoneyDisplay";
import type { MoneyInput } from "@/utils/money";

export type MoneyTextProps = {
    value: MoneyInput;
    currency?: string | null;
    showCurrency?: boolean;
    color?: string;
    style?: StyleValue;
    bold?: boolean;
};

export const MoneyText = defineComponent({
    name: "MoneyText",
    props: {
        value: { type: [String, Number, Object] as PropType<MoneyInput>, default: null },
        currency: { type: String as PropType<string | null>, default: null },
        showCurrency: { type: Boolean, default: true },
        color: { type: String, default: "" },
        style: { type: [Object, String, Array] as PropType<StyleValue>, default: undefined },
        bold: { type: Boolean, default: false },
    },
    setup(props) {
        return () => (
            <span style={props.style}>
                <MoneyDisplay
                    amount={props.value as any}
                    currency={(props.currency || "LYD").toUpperCase()}
                    showCurrency={props.showCurrency}
                    size={props.bold ? "lg" : "md"}
                />
            </span>
        );
    },
});

export default MoneyText;
TSX
done
