import { test } from "@playwright/test";
import { ADMIN_KEY, adminSession, seedSession } from "../fixtures";
const json = (status: number, body: unknown) => ({ status, contentType: "application/json", body: JSON.stringify(body) });
test("debug gateways", async ({ page }) => {
  const errors: string[] = [];
  page.on("pageerror", (e) => errors.push(String(e)));
  page.on("console", (m) => { if (m.type() === "error") errors.push(m.text()); });
  await seedSession(page, ADMIN_KEY, adminSession);
  await page.route("**/api/v1/admin/**", (route) => route.fulfill(json(200, {})));
  await page.goto("/gateways");
  await page.waitForTimeout(2000);
  console.log(JSON.stringify({ errors, body: (await page.locator("main").innerText()).slice(0, 2000), html: (await page.locator("main").innerHTML()).slice(0, 2000) }, null, 2));
