                         </ThemedText>
                         {props.emptyDescription && (
                             <ThemedText style={{ fontSize: "13px", opacity: 0.7, textAlign: "center" }}>
                                 {t(props.emptyDescription)}
                             </ThemedText>
                         )}
                     </ThemedView>
                 );
             }

             return <>{slots.default?.()}</>;
         };
     },
     {
         slots: ["default"],
         props: [
             "loading",
             "error",
             "empty",
             "emptyTitle",
             "emptyDescription",
             "minHeight",
             "onRetry",
         ] as any,
     },
 );

 export default StateView;

