 const SUMMARY_EXPORT_CHECKS = [
     { key: "ACTIVITY_SCOPE_VERIFIED", label: "Activity scope verified" },
     { key: "ACTION_BREAKDOWN_REVIEWED", label: "Action breakdown reviewed" },
