             } else if (stepNumber === 5) {
                 await api.put(urlsMap.gatewayVersionFlows(vid), { flows: draft.value.flows });
             } else if (stepNumber === 6) {
                 if (draft.value.confirmationChannels.length > 0 || draft.value.pollPolicies.length > 0) {
