                             flatFee: draft.value.costModel.flatFee,
                             percentFee: draft.value.costModel.percentFee,
                             minFee: draft.value.costModel.minFee,
                             maxFee: draft.value.costModel.maxFee,
                             currency: draft.value.costModel.currency,
                         },
                     });
                 }
             }
             dirty.value = false;
             showSnackBar({ type: "success", message: t("Saved") });
             return true;
         } catch (e) {
             saveError.value = extractApiErrorMessage(e);
             showSnackBar({ type: "error", message: saveError.value });
             return false;
         } finally {
             saving.value = false;
         }
     };

     const onChange = (next: WizardDraft) => {
         draft.value = next;
         dirty.value = true;
     };

     const goToStep = async (target: number) => {
         if (target === step.value) return;
         if (dirty.value && !(await saveStep(step.value))) return;
         step.value = target;
     };

     const goNext = async () => {
         if (step.value < STEPS.length) await goToStep(step.value + 1);
     };

     const goBack = async () => {
         if (step.value > 1) await goToStep(step.value - 1);
     };

     const stepProps = () => ({
         model: draft.value,
         onChange,
         onSave: () => saveStep(step.value),
         saving: saving.value,
         error: saveError.value,
     });

     return () => (
         <ScreenContainer>
             <ThemedView style={{ gap: "18px" }}>
                 <PageHeader
                     title={t("Gateway Wizard")}
+                    subtitle={t("Eight steps from identity to a governed live release.")}
                     end={() => (
                         <ThemedView style={{ flexDirection: "row", gap: "8px", flexWrap: "wrap", justifyContent: "flex-end" }}>
                             {gatewayCode.value && <MetaPill variant="tonal" size="small">{gatewayCode.value}</MetaPill>}
                             {versionNumber.value !== null && <MetaPill variant="tonal" size="small">v{versionNumber.value} · {versionState.value || t("Draft")}</MetaPill>}
                             <MetaPill color={dirty.value ? "warning" : "primary"} variant="tonal" size="small">
                                 {dirty.value ? t("Unsaved changes") : `${t("Step")} ${step.value} ${t("of Steps")} ${STEPS.length}`}
                             </MetaPill>
                         </ThemedView>
                     )}
                 />

                 {error.value ? (
                     <StateView error={error.value} onRetry={() => void load()} />
                 ) : loading.value ? (
                     <StateView loading={true} />
                 ) : (
                     <>
                         {versionState.value === "LIVE" && (
                             <VAlert type="warning" variant="tonal">
                                 {t("You are editing the version that is currently LIVE. Review each change carefully before saving.")}
                             </VAlert>
                         )}
                         <VStepper modelValue={step.value} onUpdate:modelValue={(v: unknown) => void goToStep(Number(v))} flat style={{ background: "transparent" }}>
                             <VStepperHeader>
                                 {STEPS.map((item) => (
                                     <VStepperItem key={item.key} title={t(item.title)} value={STEPS.indexOf(item) + 1} />
                                 ))}
                             </VStepperHeader>
                             <VStepperWindow>
                                 <VStepperWindowItem value={1}>
                                     <StepIdentity {...stepProps()} />
                                 </VStepperWindowItem>
                                 <VStepperWindowItem value={2}>
                                     <StepEnvironments {...stepProps()} />
                                 </VStepperWindowItem>
                                 <VStepperWindowItem value={3}>
                                     <StepCustomerCatalog {...stepProps()} />
                                 </VStepperWindowItem>
                                 <VStepperWindowItem value={4}>
                                     <StepCryptoProfile {...stepProps()} />
                                 </VStepperWindowItem>
                                 <VStepperWindowItem value={5}>
                                     <StepFlowBuilder {...stepProps()} />
                                 </VStepperWindowItem>
                                 <VStepperWindowItem value={6}>
                                     <StepClientAction {...stepProps()} />
                                 </VStepperWindowItem>
                                 <VStepperWindowItem value={7}>
                                     <StepStatusRules {...stepProps()} />
                                 </VStepperWindowItem>
                                 <VStepperWindowItem value={8}>
                                     <StepSimulator {...stepProps()} />
                                 </VStepperWindowItem>
                             </VStepperWindow>
                         </VStepper>

                         {saveError.value && (
                             <VAlert type="error" variant="tonal" density="compact">
                                 {saveError.value}
                             </VAlert>
                         )}

                         <ThemedView style={{ flexDirection: "row", justifyContent: "space-between", gap: "12px" }}>
                             <VBtn variant="tonal" disabled={step.value <= 1 || saving.value} onClick={() => void goBack()}>
                                 {t("Back")}
                             </VBtn>
                             <ThemedView style={{ flexDirection: "row", gap: "10px" }}>
                                 <VBtn
                                     variant="text"
                                     loading={saving.value}
                                     onClick={async () => {
                                         const ok = await saveStep(step.value);
                                         if (ok) {
                                             showSnackBar({ type: "success", message: t("Saved") });
                                         }
                                     }}
                                 >
                                     {t("Save")}
                                 </VBtn>
                                 {step.value < STEPS.length && (
                                     <VBtn color="primary" loading={saving.value} onClick={() => void goNext()}>
                                         {t("Continue")}
                                     </VBtn>
                                 )}
                                 {step.value === STEPS.length && (
                                     <VBtn variant="text" onClick={() => void router.push({ name: "Gateways" })}>
                                         {t("Close")}
                                     </VBtn>
                                 )}
                             </ThemedView>
                         </ThemedView>
                     </>
                 )}
             </ThemedView>
         </ScreenContainer>
     );
 });

 export default GatewayWizardPage;

