     { key: "CHECKER_SCOPE_CONFIRMED", label: "Checker scope confirmed" },
 ] as const;

 export type MerchantEditMode = "DESCRIPTIVE" | "SENSITIVE";

 type EditForm = {
     tradeName: string;
     displayName: string;
     logoUrl: string;
     supportEmail: string;
