 const formatCapabilities = (value: unknown): string => {
     if (Array.isArray(value)) {
         return value.join(", ");
     }
     if (value && typeof value === "object") {
         return Object.entries(value as Record<string, unknown>)
             .filter(([, enabled]) => enabled === true)
             .map(([key]) => key)
             .join(", ");
     }
     return "";
 };

