                                       }
                                     : undefined
                             }
                             refresh={refresh}
                             Icon={props.Icon}
                             iconName={props.iconName}
                         ></TableHeader>

                         {server.value?.filters?.length ? (
                             <TableFilters
                                 filters={server.value.filters}
                                 values={serverFilterValues.value}
                                 total={serverTotal.value}
                                 onChange={(key, value) => {
                                     serverFilterValues.value = { ...serverFilterValues.value, [key]: value };
