                             >
                                 <ThemedText style={{ flex: 1, fontSize: "13px" }}>{serverError.value}</ThemedText>
                                 <VBtn size="small" variant="tonal" color="error" onClick={() => scheduleServerFetch()}>
                                     {t("Retry")}
                                 </VBtn>
                             </ThemedView>
