import { expect, test, type Page } from "@playwright/test";

const ADMIN = process.env.PG_ADMIN_URL ?? "http://127.0.0.1:8443";
const MERCHANT = process.env.PG_MERCHANT_URL ?? "http://127.0.0.1:8444";
const CHECKOUT = process.env.PG_CHECKOUT_URL ?? "https://127.0.0.1:8445";
