import { expect, test, type Page } from "@playwright/test";
const ADMIN = "http://127.0.0.1:8443";
const MERCHANT = "http://127.0.0.1:8444";
const CHECKOUT = "https://127.0.0.1:8445";
const PASSWORD = "Mayallahhelpme@96";
const login = async (page: Page, base: string, label: string, email: string) => {
  await page.goto(`${base}/login`, { waitUntil: "domcontentloaded" });
  await page.getByLabel(label).fill(email);
  await page.locator('input[type="password"]').first().fill(PASSWORD);
  await page.getByRole("button", { name: "Login", exact: true }).click();
};
test("live visual contract", async ({ page }) => {
  const errors: string[] = [];
  const external: string[] = [];
  await page.addInitScript(() => { window.localStorage.clear(); window.localStorage.setItem("locale-name", "en"); });
  page.on("pageerror", (error) => errors.push(String(error)));
  page.on("console", (message) => { if (message.type() === "error") errors.push(message.text()); });
  page.on("request", (request) => {
    const url = new URL(request.url());
    if (!["127.0.0.1", "localhost"].includes(url.hostname) && !url.hostname.endsWith(".npay.ly")) external.push(request.url());
  });

  await login(page, ADMIN, "Email or phone", "admin@pg.dev");
  await expect(page).toHaveURL(/\/dashboard/);
  await page.locator(".pg-page").waitFor();
  expect(await page.evaluate(() => getComputedStyle(document.body).fontFamily)).toContain("Plus Jakarta Sans");
  await expect(page.locator(".pg-drawer")).toBeVisible();
  await expect(page.locator(".pg-app-bar")).toBeVisible();
  expect(await page.evaluate(() => document.documentElement.scrollWidth <= document.documentElement.clientWidth + 1)).toBe(true);
  const runtime = await page.evaluate(() => (window as any).__PG_RUNTIME_CONFIG__);
  expect(runtime.showChecklists).toBe(false);
  expect(runtime.showHelpPanels).toBe(false);

  await page.goto(`${ADMIN}/gateways`, { waitUntil: "domcontentloaded" });
  await expect(page.locator(".pg-page")).toBeVisible();
  await page.getByRole("button", { name: "New Gateway" }).click();
  await expect(page.getByRole("heading", { name: "New Gateway" })).toBeVisible();
  await expect(page.getByLabel("Gateway name", { exact: true })).toBeVisible();
  await page.getByRole("button", { name: "Cancel", exact: true }).click();

  await page.goto(`${ADMIN}/finance/invariant`, { waitUntil: "domcontentloaded" });
  await expect(page.locator(".pg-page")).toBeVisible();

  await login(page, MERCHANT, "Phone Or Email", "mr@pg.dev");
  await expect(page).toHaveURL(/\/portal\/dashboard/);
  await expect(page.locator(".pg-page")).toBeVisible();
  await page.getByRole("button", { name: "Language" }).click();
  await page.getByText("العربية", { exact: true }).click();
  await page.waitForTimeout(400);
  expect(await page.evaluate(() => getComputedStyle(document.body).fontFamily)).toContain("Cairo");
  expect(await page.evaluate(() => document.documentElement.dir)).toBe("rtl");

  await page.goto(`${CHECKOUT}/pay/does-not-exist`, { waitUntil: "domcontentloaded" });
  await expect(page.locator(".pg-checkout")).toBeVisible();
  expect(await page.evaluate(() => document.documentElement.scrollWidth <= document.documentElement.clientWidth + 1)).toBe(true);

  expect(external, `external asset requests: ${external.join(", ")}`).toEqual([]);
  const unexpected = errors.filter((error) => !error.includes("api/v1/pay/does-not-exist") && !error.includes("Failed to load resource"));
  expect(unexpected, `browser errors: ${unexpected.join(" | ")}`).toEqual([]);
});
