   color: var(--pg-bg-surface) !important;
 }

 ::selection {
   background: var(--pg-accent-interactive-soft);
   color: var(--pg-ink-primary);
 }

 /* Authentication shell */
 .pg-auth-shell {
   display: grid;
   grid-template-columns: minmax(0, 45%) minmax(0, 55%);
   min-height: 100dvh;
   background: var(--pg-bg-surface);
 }

 .pg-auth-aside {
   position: relative;
   display: flex;
   flex-direction: column;
   justify-content: space-between;
   gap: 32px;
   padding: 36px 40px;
   background: var(--pg-bg-surface-subtle);
   border-inline-end: 1px solid var(--pg-border-subtle);
   overflow: hidden;
 }

 .pg-auth-brand {
   display: flex;
   align-items: center;
   gap: 11px;
   position: relative;
   z-index: 1;
 }

 .pg-auth-brand__mark {
   width: 36px;
   height: 36px;
   border-radius: 8px;
   display: inline-flex;
   align-items: center;
   justify-content: center;
   background: var(--pg-ink-primary);
 }

 .pg-auth-brand__mark img {
   filter: brightness(0) invert(1);
 }

 .pg-auth-brand__title {
   font-size: 14px;
   font-weight: 600;
   color: var(--pg-ink-primary);
 }

 .pg-auth-brand__subtitle {
   font-size: 11.5px;
   color: var(--pg-ink-muted);
 }

 .pg-auth-posture {
   position: relative;
   z-index: 1;
   max-width: 46ch;
 }

 .pg-auth-posture h2 {
   margin: 0 0 12px;
   font-size: 30px;
   line-height: 1.15;
   letter-spacing: -0.03em;
   color: var(--pg-ink-primary);
 }

 .pg-auth-posture p {
   margin: 0;
   font-size: 13.5px;
   line-height: 1.65;
   color: var(--pg-ink-secondary);
 }

 .pg-auth-badges {
   display: flex;
   flex-wrap: wrap;
   gap: 7px;
   margin-top: 20px;
 }

 .pg-auth-aside__footer {
   display: flex;
   align-items: center;
   gap: 7px;
   position: relative;
   z-index: 1;
   font-size: 12px;
   color: var(--pg-ink-muted);
 }

 .pg-auth-status-dot {
   width: 6px;
   height: 6px;
   border-radius: 999px;
   background: var(--pg-status-success-dot);
 }

 .pg-auth-main {
   display: flex;
   align-items: center;
   justify-content: center;
   padding: 32px 24px;
   background: var(--pg-bg-surface);
 }

 .pg-auth-panel {
   width: 100%;
   max-width: 400px;
 }

 @media (max-width: 960px) {
   .pg-auth-shell {
     grid-template-columns: 1fr;
   }

   .pg-auth-aside {
     display: none;
   }

   .pg-auth-main {
     min-height: 100dvh;
     padding: 24px 16px 48px;
   }
 }
+
+/* Interactive primitive focus states */
+.pg-mono-ref:focus-visible,
+.pg-surface-interactive:focus-visible,
+.pg-segmented-tab:focus-visible {
+  outline: 2px solid var(--pg-border-focus);
+  outline-offset: 2px;
+}
+
+.pg-mono-ref {
+  font-family: var(--pg-font-mono) !important;
+  direction: ltr;
+  unicode-bidi: embed;
+}
+
+/* Slide-over inspection drawer */
+.pg-slide-over {
+  background: var(--pg-bg-surface) !important;
+  border-inline-start: 1px solid var(--pg-border-subtle) !important;
+  box-shadow: var(--pg-shadow-modal) !important;
+}
+
+.pg-slide-over .v-navigation-drawer__content {
+  background: var(--pg-bg-surface);
+}

