     const pairs = selected
         .filter((field) => parsed[field] !== undefined)
         .sort()
         .map((field) => `${field}=${String(parsed[field])}`);
     if (canonicalization === "SORTED_VALUES_HASH") {
         return pairs.map((pair) => pair.split("=")[1] ?? "").join("");
     }
     return pairs.join("&");
