                 value: String(data.open),
                 subLabel: t("SLA-bound requests"),
                 badge: t("Live"),
                 badgeTone: "info" as const,
             },
             {
                 key: "overdue",
                 label: t("Overdue"),
                 value: String(data.overdue),
                 subLabel: t("Past SLA"),
                 badge: data.overdue > 0 ? t("P1") : t("Clear"),
                 badgeTone: data.overdue > 0 ? "danger" as const : "success" as const,
             },
             {
