 };

 const PUBLIC_TYPES = ["TEXT", "NUMBER", "PHONE", "NATIONAL_ID", "PASSPORT", "DATE", "OTP", "HIDDEN"];

 const CORE_TO_PUBLIC: Record<string, string> = {
     string: "TEXT",
     number: "NUMBER",
     phone: "PHONE",
     otp: "OTP",
     birth_year: "DATE",
     card_number: "TEXT",
     pan: "TEXT",
