 const FilterContainer = dc(
     <
         T extends {
             [key: string]: any;
         },
     >(props: {
         filters: T;
         showActiveFilters?: boolean;
         setFilter: (key: keyof T, value: any) => void;
         onApply: () => void;
         onClear: () => void;
         loading: boolean;
         disabled: boolean;
         filtersDescription: FilterField<any, keyof T>[];
     }) => {
         const { t } = useLocale();
         const valid = ref(false);
         return () => {
             if (!props.filtersDescription.length) {
                 return <></>;
             }
             return (
                 <ThemedView
                     style={{
                         gap: "16px",
                         padding: "16px 0px",
                     }}
                 >
                     <ActiveFilters<any>
                         clear={props.onClear}
                         filters={props.filters}
                         filtersDescriptions={props.filtersDescription as any}
                         setFilters={props.setFilter}
                     ></ActiveFilters>

                     <VForm
                         disabled={props.disabled}
                         onSubmit={(e) => {
                             e.preventDefault();
                             props.onApply();
                         }}
                         modelValue={valid.value}
                         onUpdate:modelValue={(v) => {
                             valid.value = !!v;
                         }}
                     >
                         <ThemedView
                             style={{
                                 flexDirection: "row",
                                 gap: "16px",
                                 alignItems: "flex-start",
                                 flexWrap: "wrap",
                             }}
                         >
                             {props.filtersDescription.map((f) => {
                                 let filterField: JSX.Element = <></>;

                                 if (f.type == "text") {
                                     filterField = (
                                         <TextField
                                             modelValue={props.filters[f.key]}
                                             onUpdate:modelValue={(v) => {
                                                 props.setFilter(f.key, isEmpty(v) ? undefined : v);
                                             }}
                                             clearable
                                             onClick:clear={() => {
                                                 props.setFilter(f.key, undefined);
                                             }}
                                             type={f.fieldType}
                                             rules={f.rules}
                                             label={t(f.label)}
                                             name={f.key?.toString()}
                                         ></TextField>
                                     );
                                 } else if (f.type == "data-autocomplete") {
                                     filterField = (
                                         <Autocomplete
                                             name={f.key?.toString()}
                                             label={t(f.label)}
                                             items={f.items}
                                             itemTitle={f.itemTitle}
                                             itemValue={f.itemValue}
                                             modelValue={props.filters[f.key]}
                                             onUpdate:modelValue={(v) => {
                                                 props.setFilter(f.key, isEmpty(v) ? undefined : v);
                                             }}
                                             multiple={f.multiple}
                                             chips={f.multiple}
                                             closableChips={f.multiple}
                                             clearable
                                             onClick:clear={() => {
                                                 props.setFilter(f.key, undefined);
                                             }}
                                             rules={f.rules}
                                         ></Autocomplete>
                                     );
                                 } else if (f.type == "api-autocomplete") {
                                     filterField = (
                                         <ApiAutocomplete
                                             apiDataExtractor={f.apiDataExtractor}
                                             url={f.url}
                                             name={f.key?.toString()}
                                             label={t(f.label)}
                                             itemTitle={f.itemTitle}
                                             itemValue={f.itemValue}
                                             modelValue={props.filters[f.key]}
                                             onUpdate:modelValue={(v) => {
                                                 props.setFilter(f.key, isEmpty(v) ? undefined : v);
                                             }}
                                             multiple={f.multiple}
                                             chips={f.multiple}
                                             closableChips={f.multiple}
                                             clearable
                                             onClick:clear={() => {
                                                 props.setFilter(f.key, undefined);
                                             }}
                                             rules={f.rules}
                                         ></ApiAutocomplete>
                                     );
                                 } else if (f.type == "date-input") {
                                     filterField = (
                                         <DateInput
                                             name={f.key?.toString()}
                                             rules={f.rules}
                                             label={t(f.label)}
                                             modelValue={props.filters[f.key]}
                                             onUpdate:modelValue={(v) => {
                                                 props.setFilter(f.key, isEmpty(v) ? undefined : v);
                                             }}
                                             clearable
                                             onClick:clear={() => {
                                                 props.setFilter(f.key, undefined);
                                             }}
                                         ></DateInput>
                                     );
                                 }

                                 return (
                                     <ThemedView
                                         key={f.key}
                                         style={{
                                             flex: "1",
                                             minWidth: "200px",
                                         }}
                                     >
                                         {filterField}
                                     </ThemedView>
                                 );
                             })}
                         </ThemedView>
                     </VForm>

                     <Button
                         variant="text"
                         label="Apply Filters"
                         disabled={!valid.value || props.loading}
                         loading={props.loading}
                         onClick={() => {
                             props.onApply();
                         }}
                     ></Button>
                 </ThemedView>
             );
         };
     },
     {
         props: ["disabled", "showActiveFilters", "filters", "filtersDescription", "loading", "onApply", "onClear", "setFilter"] as any,
     },
 );
 export default FilterContainer;

